  if (KIT_K && typeof KIT_K.tex === 'function') { try { t = KIT_K.tex(name); } catch (e) { t = null; } if (t) t = t.clone(); }
  if (!t) { t = new THREE.TextureLoader().load(TEXTURES[name]); }
