function std(o, role) { const m = new THREE.MeshStandardMaterial(o); if (role) m.userData.kitRole = role; m.userData.kit = 'cyber'; return m; }
function basic(o) { const m = new THREE.MeshBasicMaterial(Object.assign({ toneMapped: false }, o)); m.userData.kit = 'cyber'; return m; }
// Shared kit materials (made once, reused by every piece)
