  slab: () => std({ map: loadTex('slab'), normalMap: loadTex('slab_n', { srgb: false }), roughness: .78, color: 0xb4b4bc }, 'slab'),
  concrete: () => std({ map: loadTex('concrete'), normalMap: loadTex('concrete_n', { srgb: false }), roughness: .85, color: 0xa8a8b0 }, 'paving'),
  mud: () => std({ map: loadTex('mud'), normalMap: loadTex('mud_n', { srgb: false }), roughness: .95 }),
  turf: () => std({ map: loadTex('turf'), roughness: .9, color: 0x7a9a88 }),
  facA: () => std({ map: loadTex('facA'), emissiveMap: loadTex('facA_e'), emissive: 0xffffff, emissiveIntensity: 1.4, roughness: .82, metalness: .1 }),
  facB: () => std({ map: loadTex('facB'), emissiveMap: loadTex('facB_e'), emissive: 0xffffff, emissiveIntensity: 1.4, roughness: .45, metalness: .5 }),
  facC: () => std({ map: loadTex('facC'), emissiveMap: loadTex('facC_e'), emissive: 0xffffff, emissiveIntensity: 1.4, roughness: .88 }),
  podium: () => std({ map: loadTex('podium'), roughness: .7, metalness: .2 }),
  detail: () => std({ map: loadTex('detail', { wrap: false }), roughness: .6, metalness: .15 }),
  detailGlow: () => basic({ map: loadTex('detail', { wrap: false }), color: new THREE.Color(1.15, 1.15, 1.15) }),
  shops: () => basic({ map: loadTex('shops', { wrap: false }), color: new THREE.Color(1, 1, 1) }),
  signs: () => basic({ map: loadTex('signs', { wrap: false }), color: new THREE.Color(1.9, 1.9, 1.9) }),
  holo: () => basic({ map: loadTex('signs', { wrap: false }), color: new THREE.Color(1.6, 1.6, 1.6), transparent: true, blending: THREE.AdditiveBlending, depthWrite: false }),
  metal: () => std({ map: loadTex('metal', { wrap: false }), normalMap: loadTex('metal_n', { srgb: false, wrap: false }), roughness: .55, metalness: .6 }),
  foliage: () => std({ map: loadTex('foliage', { wrap: false }), alphaTest: .45, side: THREE.DoubleSide, roughness: .9 }),
  foliageGlow: () => basic({ map: loadTex('foliage', { wrap: false }), alphaTest: .45, side: THREE.DoubleSide, color: new THREE.Color(2.2, 2.2, 2.2) }),
  dark: () => std({ color: 0x0d0e12, roughness: .55, metalness: .4 }),
  glass: () => std({ color: 0x2a3a50, roughness: .05, metalness: .6, envMapIntensity: 1.8, transparent: true, opacity: .42, depthWrite: false }),
  water: () => std({ color: 0x0b2a26, normalMap: loadTex('water_n', { srgb: false }), roughness: .08, metalness: .3, emissive: 0x0a3a2a, emissiveIntensity: .6 }),
  toxic: () => std({ color: 0x1a4a10, normalMap: loadTex('water_n', { srgb: false }), roughness: .1, metalness: .2, emissive: 0x38ff40, emissiveIntensity: .3 }),
  neon: () => basic({ vertexColors: true }),
  neonAdd: () => basic({ vertexColors: true, transparent: true, opacity: .85, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide }),
