  for (let i = 0; i < n; i++) { const t = i / (n - 1), x = x0 + (x1 - x0) * t, z = z0 + (z1 - z0) * t, yy = y - Math.sin(t * Math.PI) * sag;
    b.push('detailGlow', uvRect(new THREE.CylinderGeometry(.28, .28, .55, 10, 1, true), 'lant' + (i % 4)), b.tf([x, yy, z])); b.push('dark', new THREE.CylinderGeometry(.2, .2, .06, 8), b.tf([x, yy + .3, z])); }
