  const M = b.tf([x, 0, z], [0, ry, 0]); const T = (p, r = [0, 0, 0]) => M.clone().multiply(b.tf(p, r));
  b.push('metal', uvRect(new THREE.CylinderGeometry(.08, .1, 5, 8), 'metal'), T([0, 2.65, 0])); b.push('metal', uvRect(new THREE.BoxGeometry(3.4, .1, .1), 'metal'), T([-1.7, 5, 0]));
  b.push('dark', new THREE.BoxGeometry(1.1, .4, .3), T([-3, 4.7, 0]));
