function phoneBooth(b, x, z, ry, y0 = .15) { const M = b.tf([x, y0, z], [0, ry, 0]); b.push('detail', boxRect(1, .1, 1, 'sw_teal'), M.clone().multiply(b.tf([0, 2.3, 0]))); b.push('glass', new THREE.BoxGeometry(.96, 2.2, .96), M.clone().multiply(b.tf([0, 1.15, 0])));
  b.push('detailGlow', planeRect(.6, 1.2, 'phone'), M.clone().multiply(b.tf([0, 1.3, .49]))); b.push('neon', new THREE.BoxGeometry(1, .08, 1.02), M.clone().multiply(b.tf([0, 2.2, 0])), HEX(0x40ffb0, 2.4)); }
function ac(b, x, y, z, ry) { const f = new THREE.Vector3(0, 0, .26).applyAxisAngle(new THREE.Vector3(0, 1, 0), ry); b.push('detail', boxRect(.8, .6, .5, 'sw_white'), b.tf([x, y, z], [0, ry, 0])); b.push('detail', planeRect(.78, .58, 'ac'), b.tf([x + f.x, y, z + f.z], [0, ry, 0])); }
function grateDecal(b, x, z, y = .022, s = .8) { b.push('detail', planeRect(s, s, 'grate'), b.tf([x, y, z], FLAT)); }
function manhole(b, x, z, y = .024) { b.push('detail', uvRect(new THREE.CircleGeometry(.42, 20), 'manhole'), b.tf([x, y, z], FLAT)); }
function decal(b, name, x, z, w, h, ry = 0, y = .024) { b.push('detail', planeRect(w, h, name), b.tf([x, y, z], [-Math.PI / 2, ry, 0])); }
function stripe(b, x, z, len, w, ry, name = 'lineW', y = .023) { b.push('detail', uvScale(planeRect(w, len, name), 1, 1), b.tf([x, y, z], [-Math.PI / 2, ry, 0])); }
function neonPalm(b, x, z, h = 6, y0 = .15) { const segs = Math.round(h / .5); let px = x, pz = z; const lean = b.R(-.4, .4), lz = b.R(-.4, .4);
  for (let i = 0; i < segs; i++) { const t = i / segs; const nx = x + lean * t * t * 2, nz = z + lz * t * t * 2; b.push('metal', uvRect(new THREE.CylinderGeometry(.16 - t * .05, .18 - t * .05, .5, 7), 'bark'), b.tf([nx, y0 + .25 + i * .5, nz])); if (i % 2 === 0) b.push('neon', new THREE.TorusGeometry(.17 - t * .05, .015, 4, 10), b.tf([nx, y0 + .5 + i * .5, nz], [Math.PI / 2, 0, 0]), HEX(0xff40c0, 2.2)); px = nx; pz = nz; }
  const top = y0 + h; for (let i = 0; i < 9; i++) { const a = i / 9 * Math.PI * 2; b.push('foliageGlow', planeRect(2.6, 1.3, 'frond'), b.tf([px + Math.cos(a) * 1.2, top - .2, pz - Math.sin(a) * 1.2], [.0, a, -.55])); }
  b.push('neon', new THREE.SphereGeometry(.22, 8, 6), b.tf([px, top, pz]), HEX(0xff40c0, 3)); b.lamps.push([px, top - .5, pz, 0xff40c0]); }
function hoverCar(b, x, z, ry, col, y = .55) { const M = b.tf([x, y, z], [0, ry, 0]); const T = (p, r = [0, 0, 0], s) => M.clone().multiply(b.tf(p, r, s));
  b.push('metal', uvRect(new THREE.BoxGeometry(2, .55, 4.4), 'metal'), T([0, 0, 0])); b.push('glass', new THREE.BoxGeometry(1.7, .5, 2.1), T([0, .5, .2]));
  b.push('detail', boxRect(2.02, .3, 1.2, col), T([0, .05, -1.7], [.18, 0, 0])); b.push('detail', boxRect(2.02, .2, 4.2, col), T([0, .2, 0]));
  b.push('neon', new THREE.BoxGeometry(1.8, .06, .02), T([0, .05, 2.21]), HEX(0xff1030, 6)); b.push('neon', new THREE.BoxGeometry(1.7, .05, .02), T([0, .1, -2.21]), HEX(0x9ff0ff, 5));
  b.push('neonAdd', new THREE.PlaneGeometry(1.8, 4), T([0, -.29, 0], [Math.PI / 2, 0, 0]), HEX(0xff2bd6, 1.6)); for (const [tx, tz] of [[-.95, -1.4], [.95, -1.4], [-.95, 1.4], [.95, 1.4]]) b.push('dark', new THREE.CylinderGeometry(.32, .36, .18, 12), T([tx, -.25, tz])); }
function crate(b, x, z, s, y0 = .15, ry = 0) { b.push('detail', boxRect(s, s * .7, s, 'sw_wood'), b.tf([x, y0 + s * .35, z], [0, ry, 0])); }
function deadTree(b, x, z, s = 1, y0 = 0) { const br = (p, dir, len, rad, depth) => { const end = p.clone().add(dir.clone().multiplyScalar(len)); const g = uvRect(new THREE.CylinderGeometry(rad * .65, rad, len, 5), 'bark'); g.translate(0, len / 2, 0);
    g.applyQuaternion(new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize())); g.translate(p.x, p.y, p.z); b.push('metal', g);
    if (depth > 0) for (let i = 0; i < b.RI(2, 3); i++) br(end, dir.clone().add(new THREE.Vector3(b.R(-.9, .9), b.R(-.1, .5), b.R(-.9, .9))).normalize(), len * b.R(.55, .75), rad * .62, depth - (LOW ? 2 : 1)); };
  br(new THREE.Vector3(x, y0, z), new THREE.Vector3(b.R(-.1, .1), 1, b.R(-.1, .1)).normalize(), 2.6 * s, .22 * s, 4); }
function weeds(b, n, area, y0 = 0, avoid) { n = LOW ? Math.ceil(n / 2) : n; for (let i = 0; i < n; i++) { const s = b.R(.5, 1.2); const x = b.R(area[0], area[2]), z = b.R(area[1], area[3]); if (avoid && avoid(x, z)) continue;
  for (const r0 of [0, Math.PI / 2]) b.push('foliage', planeRect(s * .6, s, 'weeds'), b.tf([x, y0 + s / 2, z], [0, r0 + b.R(0, 1), 0])); } }
function fungi(b, cx, cz, col, n = 7, y0 = 0) { for (let i = 0; i < n; i++) { const s = b.R(.05, .16), px = cx + b.R(-.6, .6), pz = cz + b.R(-.6, .6), hh = b.R(.05, .25);
  b.push('neon', new THREE.SphereGeometry(s, 8, 4, 0, 6.28, 0, 1.5), b.tf([px, y0 + hh, pz]), HEX(col, 2.2)); b.push('detail', uvRect(new THREE.CylinderGeometry(s * .25, s * .3, hh, 5), 'sw_white'), b.tf([px, y0 + hh / 2, pz])); } }
function fenceRun(b, x0, z0, x1, z1, h = 2.4, y0 = 0) { const len = Math.hypot(x1 - x0, z1 - z0), ry = Math.atan2(-(z1 - z0), x1 - x0); const n = Math.max(1, Math.round(len / 2.4));
  for (let i = 0; i < n; i++) { const t = (i + .5) / n; b.push('foliage', planeRect(len / n, h, 'fence'), b.tf([x0 + (x1 - x0) * t, y0 + h / 2, z0 + (z1 - z0) * t], [0, ry, 0])); }
  for (let i = 0; i <= n; i++) { const t = i / n; b.push('metal', uvRect(new THREE.CylinderGeometry(.05, .05, h + .2, 6), 'rust'), b.tf([x0 + (x1 - x0) * t, y0 + h / 2, z0 + (z1 - z0) * t], [0, 0, b.R(-.06, .06)])); } }
function groundPlane(b, mat = 'mud', s = 8, y = .004) { b.push(mat, planeW(SQ, SQ, s), b.tf([0, y, 0], FLAT)); }
function paving(b) { b.push('slab', boxW(SQ, .15, SQ, 4), b.tf([0, .075, 0])); }

/* ================== buildings ================== */
const FACES = [0, Math.PI / 2, Math.PI, -Math.PI / 2]; // S(+z) E(+x) N(-z) W(-x)
function faceTf(b, o, f) { const ry = FACES[f], L = f % 2 ? o.d : o.w, dist = f % 2 ? o.w / 2 : o.d / 2; const nx = Math.sin(ry), nz = Math.cos(ry), ux = Math.cos(ry), uz = -Math.sin(ry);
  return { L, ry, at: (u, y, out = 0, rot = [0, 0, 0], s) => b.tf([o.cx + ux * u + nx * (dist + out), y, o.cz + uz * u + nz * (dist + out)], [rot[0], ry + rot[1], rot[2]], s) }; }
let SHOPI = 0, BANDI = 0, BLADEI = 0;
function building(b, o) {
  o = Object.assign({ cx: 0, cz: 0, w: 11, d: 11, floors: 7, style: 'A', y0: .15, ph: 4.5, shops: [1, 1, 1, 1], blades: 3, roof: true, billboard: true, trim: 0x00f0ff, ac: true }, o);
  const top = o.y0 + o.ph + o.floors * 3.2, wallH = top - o.y0 - o.ph, fac = 'fac' + o.style, uo = b.pick([0, .5]);
  for (let f = 0; f < 4; f++) { const F = faceTf(b, o, f); b.push(fac, uvScale(plane(F.L, wallH), F.L / 8, wallH / 16, uo, 0), F.at(0, o.y0 + o.ph + wallH / 2)); }
  b.push('concrete', planeW(o.w, o.d, 4), b.tf([o.cx, top, o.cz], FLAT));
  b.push(o.podiumMat || 'podium', boxW(o.w, o.ph, o.d, o.podiumMat ? 4 : 8, 4), b.tf([o.cx, o.y0 + o.ph / 2, o.cz]));
  b.push('dark', new THREE.BoxGeometry(o.w + .5, .25, o.d + .5), b.tf([o.cx, o.y0 + o.ph + .05, o.cz]));
  b.push('dark', new THREE.BoxGeometry(o.w + .3, .4, o.d + .3), b.tf([o.cx, top + .2, o.cz]));
  for (let f = 0; f < 4; f++) { const F = faceTf(b, o, f);
    if (o.skip && o.skip[f]) { /* plain face: piece dresses it */ }
    else if (o.shops[f]) { const n = Math.max(1, Math.floor(F.L / 5)), cw = F.L / n;
      for (let i = 0; i < n; i++) { const u = -F.L / 2 + cw * (i + .5), sw = Math.min(4.4, cw - .6);
        if (b.r() < .82) { b.push('shops', planeRect(sw, 2.6, 'shop' + (SHOPI++ % 14)), F.at(u, o.y0 + 1.5, .02));
          b.push('dark', new THREE.BoxGeometry(sw + .2, .12, .14), F.at(u, o.y0 + 2.86, .02)); b.push('dark', new THREE.BoxGeometry(sw + .2, .15, .14), F.at(u, o.y0 + .14, .02)); b.push('dark', new THREE.BoxGeometry(.08, 2.6, .1), F.at(u, o.y0 + 1.5, .05)); }
        else b.push('detail', planeRect(sw, 3, 'shutter'), F.at(u, o.y0 + 1.6, .02));
        if (b.r() < .55) b.push('detail', boxRect(sw, .06, 1.5, 'awn' + b.RI(0, 3)), F.at(u, o.y0 + 3.2, .72, [.25, 0, 0])); }
      b.push('signs', planeRect(Math.min(F.L - 2, 8.5), .85, 'band' + (BANDI++ % 12)), F.at(0, o.y0 + 3.9, .03));
    } else { b.push('detail', planeRect(Math.min(4.4, F.L - 1), 3, 'shutter'), F.at(b.R(-1, 1), o.y0 + 1.6, .02)); b.push('detail', planeRect(2, 1, 'poster'), F.at(F.L / 2 - 2, o.y0 + 1.6, .02)); }
    if (f < o.blades) { const hs = b.R(4.5, Math.min(8, wallH - 1)), u = (f % 2 ? -1 : 1) * (F.L / 2 - .7), y = o.y0 + o.ph + 1.5 + hs / 2 + b.R(0, Math.max(0, wallH - hs - 3)), bi = BLADEI++ % 16;
      b.push('dark', new THREE.BoxGeometry(.2, hs, 1.1), F.at(u, y, .75)); for (const sgn of [-1, 1]) b.push('signs', planeRect(1.06, hs - .06, 'blade' + bi), F.at(u + sgn * .105, y, .75, [0, sgn * Math.PI / 2, 0]));
      for (const yy of [-hs / 2 + .4, hs / 2 - .4]) b.push('metal', uvRect(new THREE.BoxGeometry(.06, .06, .5), 'metal'), F.at(u, y + yy, .2)); }
    if (o.ac) for (let k = 0; k < (LOW ? 2 : b.RI(3, 6)); k++) (() => { const M = F.at(b.R(-F.L / 2 + .6, F.L / 2 - .6), b.R(o.y0 + o.ph + 1.2, top - 1), .25); const p = new THREE.Vector3().setFromMatrixPosition(M); ac(b, p.x, p.y, p.z, F.ry); })();
    for (let k = 0; k < 2; k++) b.push('metal', uvRect(new THREE.CylinderGeometry(.06, .06, top - o.y0, 6), b.r() < .5 ? 'rust' : 'metal'), F.at(b.R(-F.L / 2 + .3, F.L / 2 - .3), (top + o.y0) / 2, .1));
    b.push('neon', new THREE.BoxGeometry(F.L, .08, .08), F.at(0, top + .42, .05), HEX(o.trim, 3)); }
  if (o.roof) { for (let n = 0; n < (LOW ? 2 : b.RI(3, 5)); n++) b.push('metal', uvRect(new THREE.BoxGeometry(b.R(1, 2.4), b.R(.8, 2), b.R(1, 2.4)), b.r() < .5 ? 'rust' : 'metal'), b.tf([o.cx + b.R(-o.w / 3, o.w / 3), top + .6, o.cz + b.R(-o.d / 3, o.d / 3)]));
    b.push('metal', uvRect(new THREE.CylinderGeometry(1.1, 1.1, 2.2, 14), 'rust'), b.tf([o.cx - o.w / 4, top + 2.6, o.cz + o.d / 4]));
    for (const [lx, lz] of [[-.7, -.7], [.7, -.7], [-.7, .7], [.7, .7]]) b.push('metal', uvRect(new THREE.CylinderGeometry(.05, .05, 1.5, 5), 'metal'), b.tf([o.cx - o.w / 4 + lx, top + .75, o.cz + o.d / 4 + lz]));
    b.push('metal', uvRect(new THREE.CylinderGeometry(.03, .06, 7, 5), 'metal'), b.tf([o.cx + o.w / 4, top + 3.5, o.cz - o.d / 4])); b.push('neon', new THREE.SphereGeometry(.14, 6, 6), b.tf([o.cx + o.w / 4, top + 7, o.cz - o.d / 4]), HEX(0xff2020, 6));
    if (o.billboard) { const bw = Math.min(7, o.w - 1); b.push('signs', planeRect(bw, bw * .48, 'billboard'), b.tf([o.cx, top + 3.2, o.cz + o.d / 2 - .8])); b.push('dark', new THREE.BoxGeometry(bw + .2, bw * .48 + .2, .2), b.tf([o.cx, top + 3.2, o.cz + o.d / 2 - .95]));
      for (const s of [-1, 1]) b.push('metal', uvRect(new THREE.BoxGeometry(.15, 1.6, .15), 'metal'), b.tf([o.cx + s * bw * .4, top + .8, o.cz + o.d / 2 - 1])); } }
  return top;
}

/* ================== road helpers ================== */
function roadBase(b) { b.push('asphalt', planeW(SQ, SQ, 8), b.tf([0, .02, 0], FLAT)); }
function tactileStrip(b, x, z, len, ry) { b.push('detail', planeRect(.6, len, 'tactile'), b.tf([x, .152, z], [-Math.PI / 2, ry, 0])); }
function dashes(b, along, fixed, from, to, ry, name = 'lineW') { for (let s = from + 1; s < to - 1; s += 4) { const c = s + 1; if (along === 'z') stripe(b, fixed, c, 2, .14, ry, name); else stripe(b, c, fixed, 2, .14, ry, name); } }
function zebra(b, cx, cz, alongX, n = 7) { for (let i = 0; i < n; i++) { const o = -4 + i * 8 / (n - 1); if (alongX) stripe(b, cx + o, cz, 2.6, .7, 0, 'zebra'); else stripe(b, cx, cz + o, 2.6, .7, Math.PI / 2, 'zebra'); } }

/* ================== CITY PIECES ================== */
const CITY = [], NATURE = [];
function piece(id, name, edges, build, tags) { (id[0] === 'C' ? CITY : NATURE).push({ id: 'CYBER-' + id, name, family: id[0], edges, size: 1, tags: tags || [], build }); }

// ---------- joiners ----------
piece('C01', 'Neon street', 'RCRC', (g, b) => {
  roadBase(b); for (const s of [-1, 1]) { slabPoly(b, rect(s * 5, -HS, s * HS, HS)); tactileStrip(b, s * 5.75, 0, SQ, 0); }
  stripe(b, -4.6, 0, SQ, .14, 0); stripe(b, 4.6, 0, SQ, .14, 0); dashes(b, 'z', 0, -HS, HS, 0);
  decal(b, 'stop', -2.5, 4.5, 3.6, 1.8); manhole(b, 1.8, -2); grateDecal(b, -4.4, -6);
  lamp(b, 5.6, -4, -1, 0); lamp(b, -5.6, 4, 1, 0);
  lanternString(b, -7.6, -6, 7.6, -6);
  neonPost(b, -7.3, -1.5, Math.PI / 2, 2); neonPost(b, 7.3, 5.5, -Math.PI / 2, 1);
  vending(b, 7.5, 1.2, -Math.PI / 2, 0); vending(b, 7.5, 2.1, -Math.PI / 2, 1);
  for (const s of [-1, 1]) for (let z = -6; z <= 6; z += 4) if (!LOW || z % 8 === 0) bollard(b, s * 5.35, z + (s > 0 ? 2 : 0), s > 0 ? 0xff9a00 : 0x00e5ff);
  trash(b, -7.5, 6, LOW ? 2 : 4); trash(b, 7.4, -6.5, 3); drum(b, -7.4, 7.3);
});
piece('C02', 'Road corner', 'RRCC', (g, b) => { // roads to N and E
  roadBase(b);
  slabPoly(b, fillet([[-HS, -HS], [-5, -HS], [-5, 5], [HS, 5], [HS, HS], [-HS, HS]], [0, 0, 4, 0, 0, 0]));
  slabPoly(b, fillet([[5, -HS], [HS, -HS], [HS, -5], [5, -5]], [0, 0, 0, 1.5]));
  const arc = (cx, cz, r, a0, a1, w, name, dash) => { const n = 10; for (let i = 0; i < n; i++) { if (dash && i % 2) continue; const am = a0 + (i + .5) / n * (a1 - a0); stripe(b, cx - Math.cos(am) * r, cz + Math.sin(am) * r, r * (a1 - a0) / n + .02, w, am, name); } };
  arc(8, -8, 8, 0, Math.PI / 2, .14, 'lineW', true); arc(-1, 1, 3.6, 0, Math.PI / 2, .14, 'lineW');
  stripe(b, -4.6, -3.5, 9, .14, 0); stripe(b, 3.5, 4.6, 9, .14, Math.PI / 2);
  lamp(b, -6.3, 6.3, .7071, -.7071); signal(b, 6.3, -6.3, 0);
  // convex traffic mirror on the inner island
  b.push('metal', uvRect(new THREE.CylinderGeometry(.05, .05, 3, 6), 'metal'), b.tf([6.6, 1.65, -5.8])); b.push('detail', uvRect(new THREE.CylinderGeometry(.42, .42, .06, 16), 'sw_yellow'), b.tf([6.6, 3.1, -5.6], [Math.PI / 2 - .2, -Math.PI / 4, 0])); b.push('glass', new THREE.CircleGeometry(.36, 16), b.tf([6.55, 3.1, -5.55], [-.2, -Math.PI * .75, 0]));
  vending(b, -7.5, 7.0, Math.PI / 2 + Math.PI / 4, 2); neonPost(b, -7.3, -4, Math.PI / 2, 5);
  for (let i = 0; i < 5; i++) { const a = (i + .5) / 5 * Math.PI / 2; bollard(b, -1 - Math.cos(a) * 4.5, 1 + Math.sin(a) * 4.5, 0x00e5ff); }
  manhole(b, 1, -1); trash(b, 7.4, 7.3, 3); tactileStrip(b, -5.75, -2, 12, 0); tactileStrip(b, 2, 5.75, 12, Math.PI / 2);
});
piece('C03', 'T-junction', 'RRRC', (g, b) => { // roads N, E, S
  roadBase(b);
  slabPoly(b, rect(-HS, -HS, -5, HS)); slabPoly(b, fillet(rect(5, -HS, HS, -5), [0, 0, 0, 1.5])); slabPoly(b, fillet([[5, 5], [HS, 5], [HS, HS], [5, HS]], [1.5, 0, 0, 0]));
  stripe(b, -4.6, 0, SQ, .14, 0); dashes(b, 'z', 0, -HS, -5.5, 0); dashes(b, 'z', 0, 5.5, HS, 0); dashes(b, 'x', 0, 5, HS, Math.PI / 2);
  zebra(b, 6.5, 0, false); stripe(b, 4.8, 0, 10, .3, 0);
  signal(b, 6.4, -6.4, 2); signal(b, 6.4, 6.4, 0); signal(b, -6.4, 0, 2);
  lamp(b, -5.6, -5, 1, 0); lamp(b, -5.6, 5, 1, 0);
  phoneBooth(b, -7.2, -1.8, Math.PI / 2); vending(b, -7.5, 1.8, Math.PI / 2, 0); neonPost(b, 7.2, -7.2, -Math.PI / 2, 9);
  manhole(b, -1.5, 2.5); grateDecal(b, 4.4, -6.5); trash(b, 7.3, 7.2, 3); tactileStrip(b, -5.75, 0, SQ, 0);
});
piece('C04', 'Scramble crossroads', 'RRRR', (g, b) => {
  roadBase(b); for (const sx of [-1, 1]) for (const sz of [-1, 1]) { const x0 = sx > 0 ? 5 : -HS, z0 = sz > 0 ? 5 : -HS; const pts = rect(x0, z0, x0 + 3, z0 + 3); const rr = [0, 0, 0, 0]; rr[sx < 0 ? (sz < 0 ? 2 : 1) : (sz < 0 ? 3 : 0)] = 1.4; slabPoly(b, fillet(pts, rr)); }
  zebra(b, 0, -6.5, true); zebra(b, 0, 6.5, true); zebra(b, -6.5, 0, false); zebra(b, 6.5, 0, false);
  for (const r of [Math.PI / 4, -Math.PI / 4]) b.push('neon', plane(.12, 12), b.tf([0, .026, 0], [-Math.PI / 2, r, 0]), HEX(0xff2bd6, 1.6));
  signal(b, 6.4, 6.4, 2); signal(b, -6.4, 6.4, 0); signal(b, -6.4, -6.4, 2); signal(b, 6.4, -6.4, 0);
  // hologram pylon on the NE corner
  b.push('metal', uvRect(new THREE.CylinderGeometry(.25, .35, 8, 10), 'metal'), b.tf([6.8, 4.15, -6.8])); b.push('dark', new THREE.CylinderGeometry(.6, .45, .5, 10), b.tf([6.8, 8.4, -6.8]));
  for (const a of [0, Math.PI / 2, Math.PI, Math.PI * 1.5]) b.push('holo', planeRect(4.6, 6.9, 'holo'), b.tf([6.8, 12.2, -6.8], [0, a - Math.PI / 4, 0]));
  b.push('neonAdd', new THREE.ConeGeometry(2.2, 3.4, 16, 1, true), b.tf([6.8, 10.3, -6.8], [Math.PI, 0, 0]), HEX(0x20a0ff, .35)); b.lamps.push([6.8, 9, -6.8, 0x40e0ff]);
  manhole(b, -2.4, 2.2); bollard(b, -5.35, -7.4, 0x00e5ff); bollard(b, 7.4, 5.35, 0xff9a00); trash(b, -7.3, 7.3, 2);
});
