/* ================== NATURE PIECES (ground @0, path @0.015) ================== */
function pathPoly(b, pts, radii) { slabPoly(b, fillet(pts, radii), .015, 'concrete', 'concrete', 0, 4); }
function rock(b, x, z, s, y0 = 0) { b.push('concrete', uvScale(new THREE.DodecahedronGeometry(s, 0), .5, .5), b.tf([x, y0 + s * .35, z], [b.R(0, 3), b.R(0, 3), b.R(0, 3)], [1, b.R(.5, .8), b.R(.8, 1.3)])); }
function fern(b, x, z, s = 1, y0 = 0) { b.push('foliage', planeRect(s, s, 'fern'), b.tf([x, y0 + .08, z], [-Math.PI / 2 + .25, b.R(0, 6), 0])); }
function oilFire(b, x, z, y0 = 0) { b.push('metal', uvRect(new THREE.CylinderGeometry(.32, .32, .95, 14, 1, true), 'rust'), b.tf([x, y0 + .48, z]));
  for (let i = 0; i < 4; i++) b.push('neonAdd', new THREE.ConeGeometry(b.R(.12, .22), b.R(.4, .8), 6, 1, true), b.tf([x + b.R(-.12, .12), y0 + 1.1 + b.R(0, .2), z + b.R(-.12, .12)]), HEX(i % 2 ? 0xff8a20 : 0xffd040, 2.4));
  b.lamps.push([x, y0 + 1.5, z, 0xff8a30]); }
function blossomTree(b, x, z, s = 1) { const ends = [];
  const br = (p, dir, len, rad, depth) => { const end = p.clone().add(dir.clone().multiplyScalar(len)); const g = uvRect(new THREE.CylinderGeometry(rad * .65, rad, len, 5), 'bark'); g.translate(0, len / 2, 0);
    g.applyQuaternion(new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize())); g.translate(p.x, p.y, p.z); b.push('metal', g);
    if (depth > 0) for (let i = 0; i < 3; i++) br(end, dir.clone().add(new THREE.Vector3(b.R(-1, 1), b.R(0, .6), b.R(-1, 1))).normalize(), len * b.R(.6, .75), rad * .6, depth - 1); else ends.push(end); };
  br(new THREE.Vector3(x, 0, z), new THREE.Vector3(b.R(-.15, .15), 1, b.R(-.15, .15)).normalize(), 2.4 * s, .25 * s, LOW ? 2 : 3);
  for (const e of ends) for (let k = 0; k < (LOW ? 1 : 2); k++) { const sz = b.R(1.4, 2.2) * s; b.push('foliage', planeRect(sz, sz, 'blossom'), b.tf([e.x + b.R(-.3, .3), e.y + b.R(-.2, .3), e.z + b.R(-.3, .3)], [b.R(-1, 1), b.R(0, 6), b.R(-.5, .5)])); }
  b.lamps.push([x, 3 * s, z, 0xffb0e0]); }
function fungusTree(b, x, z, h, col) { let p = new THREE.Vector3(x, 0, z); const segs = 6;
  for (let i = 0; i < segs; i++) { const n = p.clone().add(new THREE.Vector3(b.R(-.25, .25), h / segs, b.R(-.25, .25))); const len = n.distanceTo(p); const g = uvRect(new THREE.CylinderGeometry(.18 - i * .02, .24 - i * .02, len, 6), 'bark'); g.translate(0, len / 2, 0);
    g.applyQuaternion(new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), n.clone().sub(p).normalize())); g.translate(p.x, p.y, p.z); b.push('metal', g); p = n; }
  const caps = [[0, 1.5, 1], [-.5, 2.4, .6], [.6, 3.2, .45]]; for (const [dx, hh, sc] of caps) { if (hh > h - .2) continue; const cx = x + dx * .6, cz = z + b.R(-.4, .4), cy = Math.min(h, hh + h * .45);
    b.push('neon', new THREE.SphereGeometry(1.3 * sc, 14, 6, 0, 6.28, 0, 1.25), b.tf([cx, cy, cz], [0, 0, 0], [1, .45, 1]), HEX(col, 1.5)); b.push('dark', new THREE.CircleGeometry(1.25 * sc, 14), b.tf([cx, cy + .02, cz], [Math.PI / 2, 0, 0]));
    for (let k = 0; k < (LOW ? 2 : 5); k++) { const a = b.R(0, 6.28), rr = b.R(.4, 1.1) * sc, len = b.R(.6, 1.8); b.push('neon', new THREE.CylinderGeometry(.012, .012, len, 3), b.tf([cx + Math.cos(a) * rr, cy - len / 2, cz + Math.sin(a) * rr]), HEX(col, 2.2)); b.push('neon', new THREE.SphereGeometry(.05, 5, 3), b.tf([cx + Math.cos(a) * rr, cy - len, cz + Math.sin(a) * rr]), HEX(col, 4)); } }
  b.lamps.push([x, h * .7, z, col]); }

